const OVERPASS=['https://overpass.private.coffee/api/interpreter','https://maps.mail.ru/osm/tools/overpass/api/interpreter'];
const NSPD='https://nspd.gov.ru';
const NSPD_REFERER='https://nspd.gov.ru/map?thematic=PKK';
const NSPD_WMS_REFERER='https://nspd.gov.ru/map?active_layers=%E8%B3%90';
const NSPD_HEADERS={
 'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36',
 'Accept-Language':'ru-RU,ru;q=0.9,en;q=0.7',
 'Referer':NSPD_REFERER,
 'Origin':NSPD
};
const memo=new Map(), pending=new Map();
export function bboxOf(value,maxSpan=.08){const a=(value||'').split(',').map(Number);if(a.length!==4||a.some(x=>!Number.isFinite(x))||a[0]<-85||a[2]>85||a[1]<-180||a[3]>180||a[0]>=a[2]||a[1]>=a[3]||a[2]-a[0]>maxSpan||a[3]-a[1]>maxSpan*2)throw new Error('Некорректная или слишком большая область. Приблизьте карту.');return a;}
export function queryFor(kind,b){const box=b.join(',');const select={buildings:`way[building](${box});relation[building][type=multipolygon](${box});`,land:`way[landuse](${box});relation[landuse][type=multipolygon](${box});way[boundary=parcel](${box});`,networks:`way[man_made=pipeline](${box});way[power~"^(line|minor_line|cable)$"](${box});nwr[power~"^(substation|transformer)$"](${box});nwr[pipeline](${box});node[man_made~"^(manhole|pumping_station|water_well)$"](${box});node[emergency=fire_hydrant](${box});`,context:`nwr[amenity](${box});nwr[leisure](${box});nwr[historic](${box});nwr[public_transport](${box});nwr[shop](${box});`,roads:`way[highway](${box});way[railway](${box});`,nature:`nwr[natural](${box});way[waterway](${box});nwr[boundary=protected_area](${box});`}[kind];if(!select)throw new Error('Неизвестный слой');return `[out:json][timeout:20][maxsize:16777216];(${select});out meta geom;`;}
export async function fetchBounded(url,options={},timeout=25000){
 const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),timeout);let res;
 try{res=await fetch(url,{...options,redirect:'manual',signal:controller.signal,headers:{'User-Agent':'GeoContextDiploma/4.0 (educational GIS)',...options.headers}});}
 catch(e){clearTimeout(timer);const message=controller.signal.aborted?'Превышено время ожидания источника':e.message;console.error('upstream_fetch',new URL(url).hostname,message);throw Error(message);}
 // Keep timeout active until the response body is consumed or cancelled.
 const reader=res.body?.getReader();const body=reader?new ReadableStream({async pull(c){try{const r=await reader.read();if(r.done){clearTimeout(timer);c.close()}else c.enqueue(r.value)}catch(e){clearTimeout(timer);c.error(e)}},cancel(){clearTimeout(timer);return reader.cancel()}}):null;
 if(!reader)clearTimeout(timer);
 const wrapped=new Response(body,{status:res.status,statusText:res.statusText,headers:res.headers});
 if(!res.ok){await wrapped.body?.cancel();const e=new Error('Источник ответил HTTP '+res.status);e.httpStatus=res.status;throw e;}return wrapped;
}
export async function jsonBounded(res,max=4*1024*1024){const reader=res.body.getReader();let n=0,chunks=[];for(;;){const {done,value}=await reader.read();if(done)break;n+=value.length;if(n>max){await reader.cancel();throw Error('Слишком много данных. Приблизьте карту.')}chunks.push(value)}const bytes=new Uint8Array(n);let pos=0;for(const chunk of chunks){bytes.set(chunk,pos);pos+=chunk.length;}try{return JSON.parse(new TextDecoder().decode(bytes));}catch{throw Error('Источник вернул не JSON ('+(res.headers.get('content-type')||'неизвестный тип')+'). Ответ не принят как геоданные');}}
async function cached(key,job,ttl=300000){const old=memo.get(key);if(old&&old.expires>Date.now())return {...old.value,cached:true};if(pending.has(key))return pending.get(key);const work=job().then(value=>{if(memo.size>=4)memo.delete(memo.keys().next().value);memo.set(key,{value,expires:Date.now()+ttl});return value}).finally(()=>pending.delete(key));pending.set(key,work);return work;}
export async function osm(kind,box){const b=bboxOf(box),query=queryFor(kind,b);return cached('osm:'+kind+':'+b.join(','),async()=>{const errors=[];for(const endpoint of OVERPASS){try{const res=await fetchBounded(endpoint,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({data:query})});const data=await jsonBounded(res);if(data.remark)throw Error('Сервер не завершил запрос: '+data.remark);if(!Array.isArray(data.elements))throw Error('Нет массива объектов');return {elements:data.elements,source:'OpenStreetMap / Overpass',endpoint,sourceDate:data.osm3s?.timestamp_osm_base||null,fetchedAt:new Date().toISOString(),cached:false,bounds:b};}catch(e){errors.push(new URL(endpoint).hostname+': '+e.message);if(e.httpStatus===401||e.httpStatus===403)break;}}throw Error('Загрузка слоя не выполнена. '+errors.join('; '));});}
function validateGeometry(f,crs){if(!f.geometry)return f;const coords=f.geometry.coordinates;let max=0;const scan=a=>{if(typeof a?.[0]==='number'){max=Math.max(max,Math.abs(a[0]),Math.abs(a[1]));}else if(Array.isArray(a))a.forEach(scan);};scan(coords);const convert=/3857|900913|102100/.test(crs)||(!crs&&max>180);if(crs&&!/4326|CRS84|3857|900913|102100/.test(crs))throw Error('Неизвестная система координат источника: '+crs);const walk=a=>typeof a[0]==='number'?convert?[a[0]/6378137*180/Math.PI,(2*Math.atan(Math.exp(a[1]/6378137))-Math.PI/2)*180/Math.PI]:a:a.map(walk);return {...f,geometry:{...f.geometry,coordinates:walk(coords)}};}
export function normalizeNspd(data){const body=data.data||data;const features=body.features||body.featureCollection?.features;if(!Array.isArray(features))throw Error('Неподдерживаемый ответ кадастрового источника');const crs=body.crs?.properties?.name||data.crs?.properties?.name||'';return {type:'FeatureCollection',features:features.map(f=>validateGeometry(f,crs)),source:'НСПД',fetchedAt:new Date().toISOString()};}
function requestParam(u,name){return u.searchParams.get(name)??u.searchParams.get(name.toLowerCase())??u.searchParams.get(name.toUpperCase());}
function numericParam(u,names,min,max){const list=Array.isArray(names)?names:[names];let raw=null;for(const name of list){raw=requestParam(u,name);if(raw!==null)break;}const v=raw===null?NaN:Number(raw);if(!Number.isFinite(v)||v<min||v>max)throw Error('Неверный параметр '+list[0]);return v;}
async function cadastralSearch(q){if(!q||q.length>100||!/^\d{1,2}:\d{1,2}:\d{1,9}(?::\d{1,12})?$/.test(q))throw Error('Введите кадастровый номер участка или квартала');return cached('cad:'+q,async()=>{const url=new URL('/api/geoportal/v2/search/geoportal',NSPD);url.search=new URLSearchParams({query:q,thematicSearchId:'1'});return normalizeNspd(await jsonBounded(await fetchBounded(url,{headers:{...NSPD_HEADERS,Accept:'application/json, text/plain, */*'}},15000)));});}
// WMS is a public-source adapter, not a guarantee of service availability.
async function wms(u,identify=false){const raw=requestParam(u,'BBOX');const b=(raw||'').split(',').map(Number);if(b.length!==4||b.some(x=>!Number.isFinite(x)||Math.abs(x)>21000000)||b[0]>=b[2]||b[1]>=b[3]||b[2]-b[0]>250000||b[3]-b[1]>250000)throw Error('Некорректная область WMS');const width=numericParam(u,'WIDTH',1,2048),height=numericParam(u,'HEIGHT',1,2048);const params={SERVICE:'WMS',VERSION:'1.3.0',REQUEST:identify?'GetFeatureInfo':'GetMap',LAYERS:'36048',STYLES:'',CRS:'EPSG:3857',BBOX:b.join(','),WIDTH:String(width),HEIGHT:String(height),FORMAT:'image/png',TRANSPARENT:'TRUE'};if(identify)Object.assign(params,{QUERY_LAYERS:'36048',INFO_FORMAT:'application/json',FEATURE_COUNT:'10',I:String(numericParam(u,['X','I'],0,width-1)),J:String(numericParam(u,['Y','J'],0,height-1))});const url=new URL('/api/aeggis/v3/36048/wms',NSPD);url.search=new URLSearchParams(params);const res=await fetchBounded(url,{headers:{...NSPD_HEADERS,Referer:NSPD_WMS_REFERER,Accept:identify?'application/json, text/plain, */*':'image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8'}},15000);if(identify)return normalizeNspd(await jsonBounded(res));const contentType=res.headers.get('Content-Type')||'';if(!contentType.includes('image/'))throw Error('Кадастровый сервис не вернул изображение');return new Response(res.body,{headers:{'Content-Type':contentType,'Cache-Control':'private, max-age=300','X-Content-Type-Options':'nosniff'}});}
export async function handleApi(request){const u=new URL(request.url);if(request.method!=='GET')return Response.json({error:'Только GET'},{status:405});try{let data;if(u.pathname==='/api/objects')data=await osm(u.searchParams.get('kind'),u.searchParams.get('bbox'));else if(u.pathname==='/api/cadastre/search')data=await cadastralSearch(u.searchParams.get('q'));else if(u.pathname==='/api/cadastre/map')return await wms(u);else if(u.pathname==='/api/cadastre/identify')data=await wms(u,true);else return Response.json({error:'Маршрут не найден'},{status:404});return Response.json(data,{headers:{'Cache-Control':'private, max-age=60','X-Content-Type-Options':'nosniff'}});}catch(e){console.error('geo_api_error',u.pathname,e.message);return Response.json({error:e.message,unavailable:true,at:new Date().toISOString()},{status:e.httpStatus===403?503:502,headers:{'Cache-Control':'no-store'}});}}

